assert data.shape == (1000, 12), "Input data must be shape (1000, 12)"

# Load TFLite model

import tensorflow as tf
model_path = "cnn_quantized.tflite"
interpreter = tf.lite.Interpreter(model_path=model_path, num_threads=4)
interpreter.allocate_tensors()

input_details = interpreter.get_input_details()
output_details = interpreter.get_output_details()

input_scale, input_zero_point = input_details[0]['quantization']
output_scale, output_zero_point = output_details[0]['quantization']

# Quantize and reshape
quantized_data = (data / input_scale + input_zero_point).astype(np.int8)
input_data = quantized_data.reshape(1000, 12, 1)

interpreter.resize_tensor_input(input_details[0]['index'], input_data.shape)
interpreter.allocate_tensors()

# Inference
print("Classifying Disease using TFLite model...")
start_time = time.time()
interpreter.set_tensor(input_details[0]['index'], input_data)
interpreter.invoke()
output = interpreter.get_tensor(output_details[0]['index'])
inference_time = time.time() - start_time

# Dequantize output
output = (output.astype(np.float32) - output_zero_point) * output_scale
predicted_classes = np.argmax(output, axis=1)

# Calculate prediction distribution
unique, counts = np.unique(predicted_classes, return_counts=True)
percentages = {i: (count / len(predicted_classes)) * 100 for i, count in zip(unique, counts)}

# Top class
top_class = max(percentages, key=percentages.get)
top_label = class_labels[top_class]
top_percent = percentages[top_class]

# Console print
print(f"\nTotal Inference Time for {len(predicted_classes)} samples: {inference_time:.4f} seconds")
print("\nPrediction Distribution:")
for i in percentages:
    print(f"{class_labels[i]}: {percentages[i]:.2f}%")
print(f"\nHighest Prediction: {top_label} ({top_percent:.2f}%)")

# Summary box content
summary_text = (
    f"Total Inference Time for {len(predicted_classes)} samples: {inference_time:.4f} seconds\n\n"
    "Prediction Distribution:\n"
)
for i in percentages:
    summary_text += f"{class_labels[i]}: {percentages[i]:.2f}%\n"
summary_text += f"\nHighest Prediction: {top_label} ({top_percent:.2f}%)"

# Plot bar chart
plt.figure(figsize=(12, 6))
plt.bar(
    [class_labels[i] for i in percentages],
    [percentages[i] for i in percentages],
    color='skyblue'
)

# Larger fonts for printing
plt.title("TFLite: Predicted Class Distribution", fontsize=18)
plt.xlabel("Class", fontsize=14)
plt.ylabel("Percentage (%)", fontsize=14)
plt.xticks(rotation=25, fontsize=12)
plt.yticks(fontsize=12)

# Summary box (larger font)
plt.text(
    1.02, 0.95, summary_text,
    transform=plt.gca().transAxes,
    fontsize=12,
    verticalalignment='top',
    horizontalalignment='left',
    bbox=dict(boxstyle='round,pad=0.5', facecolor='lightyellow', edgecolor='gray')
)

plt.tight_layout()
plt.show()
